import "server-only";

import { billingConfig } from "@/lib/billing/config";
import { recoverBilling, reconcileBilling } from "@/lib/billing/jobs";
import { inngest } from "@/lib/inngest-client";
import { sweepSubscriptionLifecycle } from "@/lib/subscription-maintenance";

// One invocation every four hours keeps baseline usage within Inngest Free's monthly
// execution allowance. The operations are safe to repeat if Inngest retries.
export const billingMaintenance = inngest.createFunction(
  {
    id: "billing-maintenance",
    triggers: { cron: "0 */4 * * *" },
    concurrency: 1,
  },
  async ({ event }) => {
    // Preview deployments may share production's database.
    if (process.env.VERCEL && process.env.VERCEL_ENV !== "production")
      return { skipped: true };

    const scheduledAt = new Date(event.ts);
    if (Number.isNaN(scheduledAt.getTime()))
      throw new Error("BILLING_SCHEDULE_INVALID_TIME");

    await sweepSubscriptionLifecycle();

    billingConfig();
    const result = await recoverBilling();
    if ("disabled" in result) throw new Error("BILLING_RECOVERY_DISABLED");
    const failed =
      result.failed +
      result.checkoutFailures +
      (result.inbox && "pending" in result.inbox
        ? (result.inbox.pending ?? 0)
        : 0);
    if (failed) throw new Error("BILLING_RECOVERY_INCOMPLETE");

    if (scheduledAt.getUTCHours() === 0 && scheduledAt.getUTCMinutes() === 0) {
      billingConfig();
      await reconcileBilling();
    }

    return { complete: true };
  },
);
